void require(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
template<class F> void refuses(F action,const char* message){try{action();}catch(const std::exception&){return;}throw std::runtime_error(message);}
Json book(){return {{"revision",7},{"sheets",Json::array({{{"id","s"},{"name","Model"},{"cells",Json::array({{{"row",1},{"col",1},{"input","100"},{"style",{{"numberFormat","$#,##0.00"}}}},{{"row",1},{"col",2},{"input","0.2"}},{{"row",2},{"col",1},{"input","0.1"}},{{"row",3},{"col",1},{"input","=A1*(1+A2)"}},{{"row",3},{"col",2},{"input","=A3*B1"}}})}},{{"id","r"},{"name","Reports"},{"cells",Json::array()}}})}};}
Json address(int row,int col=1){return {{"sheet","s"},{"row",row},{"col",col}};}
Json scenario(const std::string& id="up"){return {{"id",id},{"name",id=="up"?"Upside":"Base"},{"kind","scenario"},{"cells",Json::array({{{"sheet","s"},{"row",1},{"col",1},{"type","number"},{"value",200}},{{"sheet","s"},{"row",1},{"col",3},{"type","string"},{"value","=literal"}}})}};}
void typedAssumptions(){
 const auto original=book();auto candidate=original;const auto operations=saveFinancialDefinitionOperations(original,scenario());require(original==book()&&operations.size()==1&&operations[0]["type"]=="save_financial_definition","saving a scenario returns one typed operation without changing source cells");applyFinancialModelTransaction(candidate,operations[0]);require(candidate["financialModels"][0]["version"]==1&&candidate["sheets"]==original["sheets"],"scenario definitions persist typed values without applying them");const auto apply=applyFinancialScenarioOperations(candidate,"up");require(apply.size()==1&&apply[0]["type"]=="apply_financial_scenario","applying saved assumptions is a typed transaction");applyFinancialModelTransaction(candidate,apply[0]);require(candidate["sheets"][0]["cells"][0]["input"]=="200"&&candidate["sheets"][0]["cells"][0]["style"]==original["sheets"][0]["cells"][0]["style"],"scenario application preserves existing number formats");bool literal=false;for(const auto& cell:candidate["sheets"][0]["cells"])if(cell["row"]==1&&cell["col"]==3)literal=cell["input"]=="'=literal";require(literal,"typed scenario text cannot become a formula");
 auto bad=scenario();bad["cells"][0]["row"]=3;refuses([&]{saveFinancialDefinitionOperations(original,bad);},"saved scenarios must refuse formula input targets");bad=scenario();bad["cells"].push_back(bad["cells"][0]);refuses([&]{saveFinancialDefinitionOperations(original,bad);},"duplicate scenario inputs must be refused");
 auto changed=original;applyFinancialModelTransaction(changed,operations[0]);changed["sheets"][0]["cells"][0]["input"]="=10+2";refuses([&]{applyFinancialScenarioOperations(changed,"up");},"applying a saved scenario must recheck current formula ownership");require(original==book(),"assumption preparation never mutates the caller workbook");
}
Json forecast(){return {{"id","forecast"},{"name","Revenue forecast"},{"kind","forecast"},{"periods",3},{"startPeriod",2027},{"drivers",Json::array({{{"name","Revenue"},{"base",address(1)},{"growth",address(2)},{"numberFormat","$#,##0.00"}}})},{"output",{{"sheet","r"},{"row1",1},{"col1",1}}}};}
void auditableForecast(){
 const auto original=book();CalculationEngine engine;CalculationContext context;context.snapshot=original;context.generation=23;context.evaluator=[&](const Json& candidate){return engine.calculate(candidate);};auto generated=generateFinancialModel(original,forecast(),context);require(original==book()&&generated.cells.size()==12,"forecast creation leaves source unchanged and produces a complete bounded grid");require(generated.definition["results"][0].size()==3&&std::abs(generated.definition["results"][0][2].get<double>()-133.1)<1e-9,"three forecast periods independently compound100 by10percent");require(generated.definition["sourceRevision"]==7&&generated.definition["contextGeneration"]==23&&!generated.definition["stale"].get<bool>(),"financial report results bind current workbook and calculation context");bool base=false,formula=false;for(const auto& cell:generated.cells){if(cell["row"]==2&&cell["col"]==2)base=cell["input"]=="='Model'!$A$1";if(cell["row"]==2&&cell["col"]==6)formula=cell["input"]=="=E2*(1+$C2)"&&cell["style"]["numberFormat"]=="$#,##0.00";}require(base&&formula,"forecasts contain visible source-linked assumptions and auditable compounding formulas");auto candidate=original;for(const auto& operation:financialModelOperations(original,generated))applyFinancialModelTransaction(candidate,operation);require(candidate["sheets"][0]==original["sheets"][0]&&candidate["financialModels"].size()==1,"publishing a forecast modifies only owned report cells and metadata");
 auto occupied=original;occupied["sheets"][1]["cells"].push_back({{"row",2},{"col",5},{"input","keep"}});refuses([&]{generateFinancialModel(occupied,forecast(),context);},"forecast output must refuse occupied unowned cells");refuses([&]{generateFinancialModel(original,forecast(),context,[]{return true;});},"cancelled forecast must not publish results");auto stale=context;stale.generationIsCurrent=[](auto){return false;};refuses([&]{generateFinancialModel(original,forecast(),stale);},"stale calculation contexts must be refused");auto unconverged=context;unconverged.evaluator=[](const Json& candidate){return Json{{"revision",candidate.at("revision")},{"status","ok"},{"values",Json::array()},{"iteration",{{"converged",false}}}};};refuses([&]{generateFinancialModel(original,forecast(),unconverged);},"nonconvergent forecast calculations must be refused");
}
void scenarioComparison(){
 auto original=book();for(const auto& operation:saveFinancialDefinitionOperations(original,scenario()))applyFinancialModelTransaction(original,operation);auto margin=scenario("margin");margin["name"]="Margin";margin["cells"]=Json::array({{{"sheet","s"},{"row",1},{"col",2},{"type","number"},{"value",0.5}}});for(const auto& operation:saveFinancialDefinitionOperations(original,margin))applyFinancialModelTransaction(original,operation);const auto before=original;CalculationEngine engine;CalculationContext context;context.snapshot=original;context.generation=41;int evaluations=0;context.evaluator=[&](const Json& candidate){++evaluations;return engine.calculate(candidate);};auto result=address(3,2);result["label"]="Profit";result["numberFormat"]="$#,##0.00";const Json definition={{"id","comparison"},{"name","Scenario comparison"},{"kind","scenario_comparison"},{"scenarioIds",Json::array({"up","margin"})},{"outputs",Json::array({result})},{"output",{{"sheet","r"},{"row1",10},{"col1",1}}}};
 const auto generated=generateFinancialModel(original,definition,context);require(original==before&&context.snapshot==before,"scenario comparison never mutates source inputs or prepared link state");require(evaluations==3&&generated.cells.size()==8,"comparison evaluates current model and each saved scenario exactly once");const auto& values=generated.definition.at("results");require(std::abs(values[0][0].get<double>()-22)<1e-9&&std::abs(values[1][0].get<double>()-44)<1e-9&&std::abs(values[2][0].get<double>()-55)<1e-9,"scenario evaluation resets unrelated inputs before every case");require(generated.definition["scenarioNames"]==Json::array({"Current model","Upside","Margin"}),"saved scenario names persist beside comparison values");auto candidate=original;for(const auto& operation:financialModelOperations(candidate,generated))applyFinancialModelTransaction(candidate,operation);require(candidate["sheets"][0]==original["sheets"][0]&&candidate["financialModels"].size()==3,"comparison results and saved definition publish together without applying scenarios");
 auto invalid=definition;invalid["scenarioIds"]=Json::array({"up","missing"});refuses([&]{generateFinancialModel(original,invalid,context);},"missing saved scenarios must be refused");bool live=true;auto stale=context;stale.generationIsCurrent=[&](auto){return live;};stale.evaluator=[&](const Json& value){live=false;return engine.calculate(value);};refuses([&]{generateFinancialModel(original,definition,stale);},"context changes during scenario evaluation must not publish results");
}
void savedSensitivity(){
 const auto original=book();CalculationEngine engine;CalculationContext context;context.snapshot=original;context.generation=54;int evaluations=0;context.evaluator=[&](const Json& candidate){++evaluations;return engine.calculate(candidate);};auto input=address(1);input["values"]=Json::array({100,200});auto result=address(3);result["label"]="Revenue";result["numberFormat"]="$#,##0.00";Json specification={{"id","sensitivity"},{"name","Revenue sensitivity"},{"kind","sensitivity"},{"inputs",Json::array({input})},{"result",result},{"output",{{"sheet","r"},{"row1",20},{"col1",1}}}};
 auto generated=generateFinancialModel(original,specification,context);require(generated.cells.size()==6&&evaluations==3,"one-variable sensitivity evaluates a numeric baseline and each isolated sample");require(std::abs(generated.definition["results"][0][0].get<double>()-110)<1e-9&&std::abs(generated.definition["results"][1][0].get<double>()-220)<1e-9,"one-variable saved report has independent numerical expectations");auto growth=address(2);growth["values"]=Json::array({0.1,0.2});specification["inputs"].push_back(growth);evaluations=0;generated=generateFinancialModel(original,specification,context);require(generated.cells.size()==9&&evaluations==5,"two-variable sensitivity evaluates exactly four combinations plus baseline");const auto& values=generated.definition["results"];require(std::abs(values[0][0].get<double>()-110)<1e-9&&std::abs(values[0][1].get<double>()-220)<1e-9&&std::abs(values[1][0].get<double>()-120)<1e-9&&std::abs(values[1][1].get<double>()-240)<1e-9,"saved two-variable results align first input across columns and second down rows");auto candidate=original;for(const auto& operation:financialModelOperations(candidate,generated))applyFinancialModelTransaction(candidate,operation);require(candidate["sheets"][0]==original["sheets"][0]&&candidate["financialModels"][0]["inputs"]==specification["inputs"]&&candidate["financialModels"][0]["results"]==values,"sensitivity inputs, results and owned report persist atomically without changing model inputs");
 auto invalid=specification;invalid["inputs"][0]["row"]=3;refuses([&]{generateFinancialModel(original,invalid,context);},"sensitivity must never overwrite formula changing cells");invalid=specification;invalid["inputs"][0]["values"]=Json::array({"0.1"});refuses([&]{generateFinancialModel(original,invalid,context);},"sensitivity samples must be typed numbers");invalid=specification;invalid["inputs"].push_back(input);refuses([&]{generateFinancialModel(original,invalid,context);},"more than two sensitivity inputs must be refused");evaluations=0;refuses([&]{generateFinancialModel(original,specification,context,[&]{return evaluations>=2;});},"cancellation during the sample grid refuses publication");require(original==book()&&context.snapshot==book(),"all completed and cancelled sensitivity cases leave original and prepared context unchanged");
}
void ownershipAndStaleResults(){
 auto original=book();CalculationEngine engine;CalculationContext context;context.snapshot=original;context.generation=61;context.evaluator=[&](const Json& candidate){return engine.calculate(candidate);};auto generated=generateFinancialModel(original,forecast(),context);auto candidate=original;for(const auto& operation:financialModelOperations(candidate,generated))applyFinancialModelTransaction(candidate,operation);validateFinancialModels(candidate);
 refuses([&]{validateFinancialModelEdit(candidate,{{"type","set_cell"},{"sheet","r"},{"row",2},{"col",4},{"input","999"}});},"manual edits must not overwrite owned forecast formulas");refuses([&]{validateFinancialModelEdit(candidate,{{"type","clear_range"},{"sheet","r"},{"row1",1},{"col1",1},{"row2",3},{"col2",8}});},"clear operations must not erase generated financial reports");refuses([&]{validateFinancialModelEdit(candidate,{{"type","set_metadata"},{"key","financialModels"},{"value",Json::array()}});},"generic metadata replacement cannot bypass financial ownership");refuses([&]{validateFinancialModelEdit(candidate,{{"type","delete_sheet"},{"sheet","s"}});},"worksheets used by saved financial models cannot be silently deleted");validateFinancialModelEdit(candidate,{{"type","set_style"},{"sheet","r"},{"row",2},{"col",4},{"style",{{"fill","#123456"}}}});
 refuses([&]{validateFinancialModelEdit(candidate,{{"type","replace_pivot"},{"definition",{{"source",{{"sheet","r"},{"row1",1},{"col1",1},{"row2",2},{"col2",6}}},{"output",{{"sheet","r"},{"row1",100},{"col1",1},{"row2",102},{"col2",2}}}}}});},"native pivot sources cannot introduce report feedback through owned financial output");
 invalidateFinancialModels(candidate,{{"type","set_cell"},{"sheet","s"},{"row",1},{"col",1},{"input","200"}});require(candidate["financialModels"][0]["stale"],"source changes mark committed financial results stale");candidate["sheets"][0]["cells"][0]["input"]="200";candidate["revision"]=8;for(auto& cell:candidate["sheets"][1]["cells"])if(cell["row"]==2&&cell["col"]==4)cell["style"]["fill"]="#123456";context.snapshot=candidate;generated=generateFinancialModel(candidate,forecast(),context);for(const auto& operation:financialModelOperations(candidate,generated))applyFinancialModelTransaction(candidate,operation);bool styled=false;for(const auto& cell:candidate["sheets"][1]["cells"])if(cell["row"]==2&&cell["col"]==4)styled=cell["style"].value("fill",std::string())=="#123456";require(styled&&!candidate["financialModels"][0]["stale"].get<bool>(),"refresh preserves user formatting and clears stale state only after successful publication");context.snapshot=candidate;require(financialModelOperations(candidate,generateFinancialModel(candidate,forecast(),context)).empty(),"unchanged financial refresh is a no-op without new history");
 for(const auto& operation:saveFinancialDefinitionOperations(candidate,scenario()))applyFinancialModelTransaction(candidate,operation);for(const auto& operation:applyFinancialScenarioOperations(candidate,"up"))applyFinancialModelTransaction(candidate,operation);require(candidate["financialModels"][0]["stale"],"applying saved scenarios invalidates dependent financial reports");
 auto feedback=original;feedback["pivots"]=Json::array({{{"version",1},{"source",{{"sheet","r"},{"row1",1},{"col1",1},{"row2",10},{"col2",10}}},{"output",{{"sheet","s"},{"row1",100},{"col1",1},{"row2",101},{"col2",2}}}}});context.snapshot=feedback;refuses([&]{generateFinancialModel(feedback,forecast(),context);},"financial output must not feed back into native pivot source rectangles");
 const auto source=candidate["sheets"][0];for(const auto& operation:deleteFinancialModelOperations(candidate,"forecast"))applyFinancialModelTransaction(candidate,operation);require(candidate["sheets"][0]==source&&candidate["sheets"][1]["cells"].empty()&&candidate["financialModels"].size()==1,"typed report deletion removes only owned output and its definition");auto unsupported=scenario("future");unsupported["version"]=2;refuses([&]{saveFinancialDefinitionOperations(original,unsupported);},"future financial schema versions must not be silently downgraded");
}
void refreshFormatting(){
 auto source=book();CalculationContext context;context.snapshot=source;auto generated=generateFinancialModel(source,forecast(),context);for(const auto& operation:financialModelOperations(source,generated))applyFinancialModelTransaction(source,operation);
 for(auto& value:source["sheets"][1]["cells"]){if(value["row"]==2&&value["col"]==4)value["style"]={{"numberFormat","0.0\"x\""},{"bold",true},{"fill","#123456"}};if(value["row"]==1&&value["col"]==1)value["style"]["bold"]=false;}
 context.snapshot=source;require(financialModelOperations(source,generateFinancialModel(source,forecast(),context)).empty(),"unchanged refresh retains manual styles without producing history");source["sheets"][0]["cells"][0]["input"]="200";source["revision"]=8;source["financialModels"][0]["stale"]=true;context.snapshot=source;generated=generateFinancialModel(source,forecast(),context);for(const auto& operation:financialModelOperations(source,generated))applyFinancialModelTransaction(source,operation);
 for(const auto& value:source["sheets"][1]["cells"]){if(value["row"]==2&&value["col"]==4)require(value["style"].at("numberFormat")=="0.0\"x\""&&value["style"].at("bold")==true&&value["style"].at("fill")=="#123456","source-only refresh must retain manually edited number format, bold and fill");if(value["row"]==1&&value["col"]==1)require(value["style"].at("bold")==false,"source-only refresh must retain manual removal of generated header bold");}
 auto changed=forecast();changed["drivers"][0]["numberFormat"]="0.000";context.snapshot=source;generated=generateFinancialModel(source,changed,context);for(const auto& operation:financialModelOperations(source,generated))applyFinancialModelTransaction(source,operation);for(const auto& value:source["sheets"][1]["cells"])if(value["row"]==2&&value["col"]==4)require(value["style"].at("numberFormat")=="0.000"&&value["style"].at("bold")==true&&value["style"].at("fill")=="#123456","explicit driver formatting changes override only that generated property");context.snapshot=source;require(financialModelOperations(source,generateFinancialModel(source,changed,context)).empty(),"formatted refreshed report remains a no-op on subsequent unchanged refresh");
}
void cachedReportSources(){
 auto source=book();CalculationContext context;context.snapshot=source;auto input=address(1);input["values"]=Json::array({100,200});auto output=address(3);output["label"]="Revenue";const Json first={{"id","cached-sensitivity"},{"name","Cached sensitivity"},{"kind","sensitivity"},{"inputs",Json::array({input})},{"result",output},{"output",{{"sheet","r"},{"row1",1},{"col1",1}}}};auto generated=generateFinancialModel(source,first,context);for(const auto& operation:financialModelOperations(source,generated))applyFinancialModelTransaction(source,operation);
 for(const auto& operation:saveFinancialDefinitionOperations(source,scenario()))applyFinancialModelTransaction(source,operation);source["sheets"][0]["cells"][0]["input"]="300";source["revision"]=8;source["financialModels"][0]["stale"]=true;context.snapshot=source;const auto before=source;auto cached=Json{{"sheet","r"},{"row",2},{"col",2},{"label","Cached result"}};
 auto sensitivity=first;sensitivity["id"]="chained-sensitivity";sensitivity["name"]="Chained sensitivity";sensitivity["result"]=cached;sensitivity["output"]["row1"]=10;refuses([&]{generateFinancialModel(source,sensitivity,context);},"stale generated sensitivity values must not become fresh constant what-if results");
 Json comparison={{"id","chained-comparison"},{"name","Chained comparison"},{"kind","scenario_comparison"},{"scenarioIds",Json::array({"up"})},{"outputs",Json::array({cached})},{"output",{{"sheet","r"},{"row1",20},{"col1",1}}}};refuses([&]{generateFinancialModel(source,comparison,context);},"scenario comparison must refuse generated cached result cells");
 auto projection=forecast();projection["id"]="chained-forecast";projection["name"]="Chained forecast";projection["drivers"][0]["base"]={{"sheet","r"},{"row",2},{"col",2}};projection["output"]["row1"]=30;refuses([&]{generateFinancialModel(source,projection,context);},"forecast sources must not treat saved sensitivity results as live assumptions");source["financialModels"][0]["stale"]=false;context.snapshot=source;refuses([&]{generateFinancialModel(source,sensitivity,context);},"even fresh report snapshots do not recalculate for new changing inputs");require(source["sheets"]==before["sheets"],"refused cached report chaining preserves all source and generated cells");
 auto ordinary=book();context.snapshot=ordinary;generated=generateFinancialModel(ordinary,forecast(),context);for(const auto& operation:financialModelOperations(ordinary,generated))applyFinancialModelTransaction(ordinary,operation);context.snapshot=ordinary;projection["drivers"][0]["base"]={{"sheet","r"},{"row",2},{"col",4}};require(generateFinancialModel(ordinary,projection,context).definition["results"][0][0].get<double>()>0,"ordinary forecast formulas remain valid recalculating sources");projection["drivers"][0]["base"]={{"sheet","r"},{"row",2},{"col",2}};require(generateFinancialModel(ordinary,projection,context).definition["results"][0][0].get<double>()>0,"explicit forecast Base/Growth columns remain readable assumptions");
}
void malformedPublication(){auto original=book();CalculationEngine engine;CalculationContext context;context.snapshot=original;context.generation=70;context.evaluator=[&](const Json& candidate){return engine.calculate(candidate);};const auto generated=generateFinancialModel(original,forecast(),context);auto bad=generated;bad.definition["output"]["row2"]=1048576;refuses([&]{financialModelOperations(original,bad);},"financial ownership rectangles must match the complete rendered report footprint");bad=generated;bad.cells.erase(bad.cells.begin());refuses([&]{financialModelOperations(original,bad);},"partial generated financial output must be refused");bad=generated;bad.cells.back()["input"]="=999";refuses([&]{financialModelOperations(original,bad);},"financial output cells must match the auditable definition");bad=generated;bad.definition["results"][0][0]=std::numeric_limits<double>::infinity();refuses([&]{financialModelOperations(original,bad);},"nonfinite financial caches must be refused");bad=generated;bad.definition["results"][0].erase(bad.definition["results"][0].begin());refuses([&]{financialModelOperations(original,bad);},"financial cache result dimensions must match the saved specification");auto stray=original;stray["sheets"][0]["cells"][0]["financialModelOwner"]="forecast";refuses([&]{generateFinancialModel(stray,forecast(),context);},"stray owner tags must never authorize removal of source values");require(original==book(),"malformed publication attempts leave the entire caller source unchanged");}
int main(){try{typedAssumptions();auditableForecast();scenarioComparison();savedSensitivity();ownershipAndStaleResults();refreshFormatting();cachedReportSources();malformedPublication();std::cout<<"financial models tests passed\n";}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
